arguments.file_text:
@page "/catalog"
@using sv_78498a9e16c447679f855641987ee80a.Components.Pages.Catalog
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-layout">
    <CatalogFilters Categories="_categories"
                    OnFilterApplied="HandleFilterApplied"
                    OnFilterCleared="HandleFilterCleared" />

    <main class="catalog-main">
        @if (_loading)
        {
            <div class="catalog-status">Loading products...</div>
        }
        else if (_error is not null)
        {
            <div class="catalog-status catalog-error">
                <p>Error loading products: @_error</p>
                <button @onclick="LoadProductsAsync">Retry</button>
            </div>
        }
        else if (_result is null || _result.Items.Count == 0)
        {
            <div class="catalog-status">No products found matching your criteria.</div>
        }
        else
        {
            <CatalogToolbar SortBy="@_sortBy"
                            Page="_page"
                            PageSize="_pageSize"
                            TotalCount="_result.TotalCount"
                            OnSortChanged="HandleSortChanged" />

            <ProductGrid Products="_result.Items"
                         OnProductSelected="HandleProductSelected"
                         OnAddToCart="HandleAddToCart" />

            <CatalogPagination Page="_page"
                               PageSize="_pageSize"
                               TotalCount="_result.TotalCount"
                               OnPageChanged="HandlePageChanged" />
        }
    </main>
</div>

@code {
    private List<string>? _categories;
    private PagedResult<Product>? _result;
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _page = 1;
    private int _pageSize = 12;
    private bool _loading;
    private string? _error;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    protected override async Task OnInitializedAsync()
    {
        await LoadCategoriesAsync();
        await LoadProductsAsync();
    }

    private async Task LoadCategoriesAsync()
    {
        try
        {
            _categories = await ProductService.GetCategoriesAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
    }

    private async Task LoadProductsAsync()
    {
        _loading = true;
        _error = null;

        try
        {
            _result = await ProductService.SearchAsync(_filter, _sortBy, _page, _pageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task HandleFilterApplied(ProductFilter filter)
    {
        _filter = filter;
        _page = 1;
        await LoadProductsAsync();
    }

    private async Task HandleFilterCleared()
    {
        _filter = new ProductFilter(null, null, null, false);
        _page = 1;
        await LoadProductsAsync();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _page = 1;
        await LoadProductsAsync();
    }

    private async Task HandlePageChanged(int page)
    {
        _page = page;
        await LoadProductsAsync();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for add-to-cart logic
        return Task.CompletedTask;
    }
}

.catalog-layout {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
}

/* Sidebar filters */
.catalog-filters {
    width: 25%;
    min-width: 220px;
    padding: 1rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    align-self: flex-start;
}

.catalog-filters h2 {
    margin-top: 0;
    font-size: 1.25rem;
}

.catalog-filters h3 {
    font-size: 1rem;
    margin: 1rem 0 0.5rem;
}

.filter-section {
    margin-bottom: 1rem;
}

.filter-checkbox {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.25rem;
    cursor: pointer;
}

.filter-section input[type="number"] {
    width: 100%;
    padding: 0.4rem;
    margin-top: 0.25rem;
    border: 1px solid #ccc;
    border-radius: 4px;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-top: 1rem;
}

.btn-apply,
.btn-clear {
    padding: 0.5rem 1rem;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-apply {
    background: #2563eb;
    color: white;
}

.btn-apply:hover {
    background: #1d4ed8;
